window.TREE={"subject":"Area III · Entity Tax Planning","key":"tcp_area3_entity_planning","brand":"Terra Prep","area":"III","law_asof":"2026-09-29","parts":[{"no":1,"name":"Area III · Entity Tax Planning","chs":["1-01","1-02","1-03","1-04"],"color":"--fam-eth"}],"chs":[{"key":"1-01","part":1,"no":1,"name":"Formation and liquidation of business entities","grp":"A","nodes":[1,2,3,4,5]},{"key":"1-02","part":1,"no":2,"name":"Tax planning for C corporations","grp":"B","nodes":[6,7,8]},{"key":"1-03","part":1,"no":3,"name":"Tax planning for S corporations","grp":"C","nodes":[9,10,11,12]},{"key":"1-04","part":1,"no":4,"name":"Tax planning for partnerships","grp":"D","nodes":[13,14,15]}],"nodes":[{"no":1,"part":1,"ch":1,"title":"Entity type identification","name":"Entity type identification","vol":1,"q":1,"cs":0,"law":0,"grp":"A"},{"no":2,"part":1,"ch":1,"title":"Entity selection/formation comparison","name":"Entity selection/formation comparison","vol":4,"q":4,"cs":0,"law":0,"grp":"A"},{"no":3,"part":1,"ch":1,"title":"Entity liquidation comparison","name":"Entity liquidation comparison","vol":1,"q":1,"cs":0,"law":0,"grp":"A"},{"no":4,"part":1,"ch":1,"title":"NOL/capital loss carryover savings","name":"NOL/capital loss carryover savings","vol":2,"q":2,"cs":0,"law":0,"grp":"A"},{"no":5,"part":1,"ch":1,"title":"SALT optimization","name":"SALT optimization","vol":2,"q":2,"cs":0,"law":0,"grp":"A"},{"no":6,"part":1,"ch":2,"title":"Timing of income/expense for planning","name":"Timing of income/expense for planning","vol":2,"q":2,"cs":0,"law":0,"grp":"B"},{"no":7,"part":1,"ch":2,"title":"C corp estimated tax","name":"C corp estimated tax","vol":2,"q":2,"cs":0,"law":0,"grp":"B"},{"no":8,"part":1,"ch":2,"title":"Proposed formation transaction","name":"Proposed formation transaction","vol":3,"q":3,"cs":0,"law":0,"grp":"B"},{"no":9,"part":1,"ch":3,"title":"Built-in gains tax planning","name":"Built-in gains tax planning","vol":2,"q":2,"cs":0,"law":0,"grp":"C"},{"no":10,"part":1,"ch":3,"title":"Terminating S election","name":"Terminating S election","vol":3,"q":3,"cs":0,"law":0,"grp":"C"},{"no":11,"part":1,"ch":3,"title":"S corp formation/distribution/loan planning","name":"S corp formation/distribution/loan planning","vol":3,"q":3,"cs":0,"law":0,"grp":"C"},{"no":12,"part":1,"ch":3,"title":"AEP vs AAA distribution election","name":"AEP vs AAA distribution election","vol":1,"q":1,"cs":0,"law":0,"grp":"C"},{"no":13,"part":1,"ch":4,"title":"Contribution of appreciated/depreciated property","name":"Contribution of appreciated/depreciated property","vol":1,"q":1,"cs":0,"law":0,"grp":"D"},{"no":14,"part":1,"ch":4,"title":"Payments to partner","name":"Payments to partner","vol":2,"q":2,"cs":0,"law":0,"grp":"D"},{"no":15,"part":1,"ch":4,"title":"Proposed partnership transaction","name":"Proposed partnership transaction","vol":4,"q":4,"cs":0,"law":0,"grp":"D"}],"stat":{"parts":1,"chs":4,"nodes":15,"q":33}};
window.QBANK={"1":[{"i":"TCP-III-A-0001","t":"Which type of business entity is best described by these characteristics: it is a state-law corporation, its owners have limited liability, it has 40 shareholders who are all U.S. individuals, it has one class of stock, and its income is reported by its shareholders in proportion to their shares?","mc":{"s":"Which type of business entity is best described by these characteristics: it is a state-law corporation, its owners have limited liability, it has 40 shareholders who are all U.S. individuals, it has one class of stock, and its income is reported by its shareholders in proportion to their shares?","d":"","o":["A C corporation, because any state-law corporation is taxed as a separate entity on its income","A general partnership, because income is reported by the owners in proportion to their interests in it","A limited partnership, because its owners report their shares of income and have limited liability","An S corporation, because it has eligible shareholders and one class of stock and elected pass-through"],"a":4,"cite":"IRC §1361(a); IRC §1361(b); IRC §1366","rat":"An S corporation is a corporation whose income, losses and credits pass through to shareholders in proportion to stock held.","ex":["A C corporation pays its own tax and does not report income to shareholders in proportion to shares held each year.","A general partnership is not a corporation and does not provide limited liability to its owners.","A limited partnership is not a corporation and needs at least one general partner with unlimited liability.","An S corporation is a corporation whose income, losses and credits pass through to shareholders in proportion to stock held."],"wt":["concept","concept","concept",""],"tags":{"area":"III","group":"A","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"An S corporation is a small business corporation with eligible shareholders and one class of stock that elects pass-through taxation.","from":"2026-01-01"}}],"2":[{"i":"TCP-III-A-0002","t":"Rex Moon owns land with a basis of $100,000 and a fair market value of $400,000, subject to a $250,000 mortgage. He is deciding whether to contribute the land to a new C corporation for all of its stock or to a new partnership in which he will have a 50% interest and share the liabilities 50%, with the partnership assuming the mortgage. Ignoring other considerations, how much more gain does he recognize on the contribution to the corporation than on the contribution to the partnership?","mc":{"s":"Rex Moon owns land with a basis of $100,000 and a fair market value of $400,000, subject to a $250,000 mortgage. He is deciding whether to contribute the land to a new C corporation for all of its stock or to a new partnership in which he will have a 50% interest and share the liabilities 50%, with the partnership assuming the mortgage. Ignoring other considerations, how much more gain does he recognize on the contribution to the corporation than on the contribution to the partnership?","d":"","o":["$25,000","$125,000","$150,000","$175,000"],"a":2,"cite":"IRC §357(c)(1); IRC §752(b); IRC §731(a)(1)","rat":"Corporation: liabilities of $250,000 exceed basis of $100,000, so gain of $150,000.","ex":["This is the gain on the partnership contribution alone, not the difference.","Corporation: liabilities of $250,000 exceed basis of $100,000, so gain of $150,000. Partnership: relief of $250,000 less his 50% share ($125,000) is a deemed distribution of $125,000, which exceeds his basis of $100,000 by $25,000. Difference $125,000.","This is the gain on the corporation contribution alone, not the difference.","Adds the two gains instead of taking the difference."],"wt":["trap","","trap","calc"],"tags":{"area":"III","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A corporation triggers gain when liabilities exceed basis; a partnership triggers gain only when the net deemed distribution from liability relief exceeds outside basis.","from":"2026-01-01","calc":1,"steps":["Corporation gain = 250,000 - 100,000 = $150,000","Partnership: relief = 250,000 - 50% x 250,000 = $125,000; gain = $125,000 - 100,000 = $25,000","Difference = $125,000"]}},{"i":"TCP-III-A-0008","t":"Lark Hill's owner expects the business to earn $300,000 a year before owner compensation and distributes all after-tax profits. If the business is a C corporation, it pays 21% tax and the owner pays 23.8% (including the net investment income tax) on the dividends. If it is an S corporation, the owner is taxed at 37% on the income after a 20% qualified business income deduction, which is not limited by wages or other rules. Ignore payroll taxes and state taxes. How much less total federal income tax results from the S corporation?","mc":{"s":"Lark Hill's owner expects the business to earn $300,000 a year before owner compensation and distributes all after-tax profits. If the business is a C corporation, it pays 21% tax and the owner pays 23.8% (including the net investment income tax) on the dividends. If it is an S corporation, the owner is taxed at 37% on the income after a 20% qualified business income deduction, which is not limited by wages or other rules. Ignore payroll taxes and state taxes. How much less total federal income tax results from the S corporation?","d":"","o":["$30,606","$56,406","$88,800","$119,406"],"a":1,"cite":"IRC §11(b); IRC §199A(a); IRC §1(h)(11)","rat":"C corporation: $300,000 x 21% = $63,000 plus 23.8% of the $237,000 distributed ($56,406) = $119,406.","ex":["C corporation: $300,000 x 21% = $63,000 plus 23.8% of the $237,000 distributed ($56,406) = $119,406. S corporation: taxable income is $240,000 after the deduction, taxed at 37% = $88,800. The difference is $30,606.","This is only the shareholder-level tax on dividends.","This is the tax on the S corporation owner, not the difference.","This is the total tax under the C corporation, not the difference."],"wt":["","trap","trap","trap"],"tags":{"area":"III","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"C corporation profits are taxed twice; pass-through profits are taxed once and may qualify for the 20% qualified business income deduction.","from":"2026-07-01","calc":1,"steps":["C: corporate tax $63,000; dividend tax $56,406; total $119,406","S: (300,000 - 0.2 x 300,000) x 37% = $88,800","Difference = $30,606"]}},{"i":"TCP-III-A-0009","t":"Mia Chen, single, will run a business that earns $400,000 a year before any compensation to her and before employer payroll tax. She compares three structures. S corporation: she takes a $150,000 salary and leaves the rest as S corporation income. C corporation: she takes a $150,000 salary and the corporation distributes all remaining after-tax profit as a qualified dividend. Partnership taxed business (or sole proprietorship): all $400,000 is self-employment earnings. Assume her ordinary rate is 35% on taxable income and qualified dividends are taxed at 23.8% including the net investment income tax, and the corporate rate is 21%. Payroll tax is only Medicare of 1.45% for the employer and 1.45% for the employee on wages; on self-employment earnings it is 2.9% on 92.35% of net earnings, half of which is deductible. Ignore Social Security tax and additional Medicare tax. The business is not a specified service business, has no employees other than Mia and no depreciable property, and her taxable income is high enough that the wage and property limits apply in full to the qualified business income deduction of 20%. What is the difference between the highest and second highest after-tax cash she keeps from the business?","mc":{"s":"Mia Chen, single, will run a business that earns $400,000 a year before any compensation to her and before employer payroll tax. She compares three structures. S corporation: she takes a $150,000 salary and leaves the rest as S corporation income. C corporation: she takes a $150,000 salary and the corporation distributes all remaining after-tax profit as a qualified dividend. Partnership taxed business (or sole proprietorship): all $400,000 is self-employment earnings. Assume her ordinary rate is 35% on taxable income and qualified dividends are taxed at 23.8% including the net investment income tax, and the corporate rate is 21%. Payroll tax is only Medicare of 1.45% for the employer and 1.45% for the employee on wages; on self-employment earnings it is 2.9% on 92.35% of net earnings, half of which is deductible. Ignore Social Security tax and additional Medicare tax. The business is not a specified service business, has no employees other than Mia and no depreciable property, and her taxable income is high enough that the wage and property limits apply in full to the qualified business income deduction of 20%. What is the difference between the highest and second highest after-tax cash she keeps from the business?","d":"","o":["$5,028","$6,651","$22,597","$29,248"],"a":3,"cite":"IRC §199A(b)(2); IRC §1402(a); IRC §11(b); IRC §1(h)(11)","rat":"S corporation: employer Medicare $2,175, S income $247,825, qualified business income deduction $49,565 (under 50% of wages), taxable income $348,260, tax $121,891, so after-tax cash is $273,759.","ex":["Gives the partnership the 20% qualified business income deduction. Without W-2 wages or property, the wage and property limit reduces that deduction to zero at her income level.","Compares the partnership with the C corporation. The S corporation, with its salary supporting the deduction, is the highest, so the comparison is between it and the partnership.","S corporation: employer Medicare $2,175, S income $247,825, qualified business income deduction $49,565 (under 50% of wages), taxable income $348,260, tax $121,891, so after-tax cash is $273,759. Partnership: self-employment tax $10,713, no deduction because there are no wages, tax $138,125, after-tax cash $251,162. C corporation: $244,511. The S corporation is highest, and it exceeds the partnership by $22,597.","Compares the S corporation with the C corporation. The partnership, at $251,162, is second highest, not the C corporation."],"wt":["concept","trap","","trap"],"tags":{"area":"III","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A pass-through with owner wages can get the 20% qualified business income deduction when the wage limit applies, while a partnership with no wages cannot, and a C corporation pays two levels of tax on distributed profit.","from":"2026-07-01","calc":1,"steps":["S corporation: employer Medicare = 150,000 x 1.45% = 2,175; S income = 400,000 - 150,000 - 2,175 = 247,825; deduction = min(20% x 247,825 = 49,565, 50% x 150,000 = 75,000) = 49,565; taxable income = 348,260; tax = 121,891; after-tax cash = 273,759","Partnership: self-employment tax = 400,000 x 92.35% x 2.9% = 10,713; taxable income = 400,000 - 5,357 = 394,643; no deduction; tax = 138,125; after-tax cash = 251,162","C corporation: corporate tax = 21% x 247,825 = 52,043; dividend = 195,782; individual tax = 52,500 + 46,596; after-tax cash = 244,511","Highest S corporation 273,759 less second highest partnership 251,162 = 22,597"]}},{"i":"TCP-III-A-0010","t":"Nell Ford is starting a business in which she will materially participate. It expects a $200,000 loss in Year 1 and $200,000 of income before any loss deduction in Year 2. Nell invests $120,000 and expects to have no other basis, and she has other income taxed at 35%. She can form an S corporation or a C corporation. The C corporation is taxed at 21% and can carry its Year 1 loss forward, deducting no more than 80% of Year 2 taxable income before the deduction. Ignore payroll tax, qualified business income deduction, and any tax on Year 2 income itself. How much greater is the cumulative federal income tax saving through Year 2 from the Year 1 loss with the S corporation than with the C corporation?","mc":{"s":"Nell Ford is starting a business in which she will materially participate. It expects a $200,000 loss in Year 1 and $200,000 of income before any loss deduction in Year 2. Nell invests $120,000 and expects to have no other basis, and she has other income taxed at 35%. She can form an S corporation or a C corporation. The C corporation is taxed at 21% and can carry its Year 1 loss forward, deducting no more than 80% of Year 2 taxable income before the deduction. Ignore payroll tax, qualified business income deduction, and any tax on Year 2 income itself. How much greater is the cumulative federal income tax saving through Year 2 from the Year 1 loss with the S corporation than with the C corporation?","d":"","o":["$28,000","$33,600","$36,400","$70,000"],"a":3,"cite":"IRC §1366(d); IRC §172(a)(2); IRC §11(b); IRC §469(h)(1)","rat":"S corporation: only $120,000 of the loss is deductible in Year 1, up to her basis (saving $42,000); the other $80,000 is suspended and deducted in Year 2 after income raises her basis (saving $28,000).","ex":["Assumes the full $200,000 is used at each entity's rate, ignoring the 80% limit for the C corporation. That gives a $28,000 difference.","This is the C corporation's saving in Year 2 ($33,600), not the excess of the S corporation's saving over it.","S corporation: only $120,000 of the loss is deductible in Year 1, up to her basis (saving $42,000); the other $80,000 is suspended and deducted in Year 2 after income raises her basis (saving $28,000). Total $70,000. C corporation: the loss carries to Year 2, where the 80% limit allows $160,000 (saving $33,600). Difference $36,400.","This is the S corporation's total saving and not the difference from the C corporation."],"wt":["calc","trap","","trap"],"tags":{"area":"III","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"An S corporation loss passes through to the shareholder subject to basis, with any excess carried forward, while a C corporation's loss is a carryforward limited to 80% of taxable income.","from":"2026-01-01","calc":1,"steps":["S corporation Year 1: deductible loss = min(200,000, 120,000 basis) = 120,000; saving 120,000 x 35% = 42,000; suspended 80,000","S corporation Year 2: Year 2 income increases basis, so suspended 80,000 is deducted; saving 80,000 x 35% = 28,000; total 70,000","C corporation Year 2: deduction = min(200,000, 80% x 200,000 = 160,000) = 160,000; saving 160,000 x 21% = 33,600","Difference = 70,000 - 33,600 = 36,400"]}}],"3":[{"i":"TCP-III-A-0003","t":"Oak Ridge Holdings owns assets worth $1,000,000 with a total basis of $400,000, all producing long-term capital gain on sale. The owner's stock basis is $400,000. The owner liquidates the company and receives all the proceeds after paying tax. Compare a liquidation as a C corporation with a liquidation as an S corporation with no built-in gains tax. The corporate rate is 21%, and the owner's capital gain rate is 20%. Ignore state tax and the net investment income tax. How much more total federal income tax results from the C corporation liquidation?","mc":{"s":"Oak Ridge Holdings owns assets worth $1,000,000 with a total basis of $400,000, all producing long-term capital gain on sale. The owner's stock basis is $400,000. The owner liquidates the company and receives all the proceeds after paying tax. Compare a liquidation as a C corporation with a liquidation as an S corporation with no built-in gains tax. The corporate rate is 21%, and the owner's capital gain rate is 20%. Ignore state tax and the net investment income tax. How much more total federal income tax results from the C corporation liquidation?","d":"","o":["$94,800","$100,800","$126,000","$220,800"],"a":2,"cite":"IRC §336(a); IRC §331(a); IRC §1366(a)","rat":"C corporation: corporate tax $126,000; the owner receives $874,000 and recognizes gain of $474,000 taxed at 20% ($94,800); total $220,800.","ex":["Counts only the shareholder-level tax under the C corporation case.","C corporation: corporate tax $126,000; the owner receives $874,000 and recognizes gain of $474,000 taxed at 20% ($94,800); total $220,800. S corporation: the $600,000 gain passes through at 20%, $120,000, and raises stock basis so the liquidation produces no further gain. Difference $100,800.","Counts only the corporate-level tax and omits the shareholder tax and the pass-through tax in the S corporation case.","This is the total tax under the C corporation liquidation, not the difference."],"wt":["concept","","concept","trap"],"tags":{"area":"III","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A C corporation liquidation is taxed at both corporate and shareholder levels; an S corporation liquidation is taxed once through pass-through gain.","from":"2026-01-01","calc":1,"steps":["C: corporate tax = 21% x $600,000 = $126,000","C: shareholder gain = (1,000,000 - $126,000) - 400,000 = $474,000; tax = $94,800","S: tax = 20% x $600,000 = $120,000","Difference = $100,800"]}}],"4":[{"i":"TCP-III-A-0004","t":"Cove Street Corp. has a net operating loss carryforward of $400,000 from years beginning after 2020. It projects 2027 taxable income of $350,000 before any net operating loss deduction, at a 21% rate. What tax saving does the carryforward produce in 2027?","mc":{"s":"Cove Street Corp. has a net operating loss carryforward of $400,000 from years beginning after 2020. It projects 2027 taxable income of $350,000 before any net operating loss deduction, at a 21% rate. What tax saving does the carryforward produce in 2027?","d":"","o":["$58,800","$67,200","$73,500","$84,000"],"a":1,"cite":"IRC §172(a)(2); IRC §172(b)(1)(A); IRC §11(b)","rat":"The deduction is limited to 80% of taxable income: 80% x $350,000 = $280,000, which is less than the carryforward.","ex":["The deduction is limited to 80% of taxable income: 80% x $350,000 = $280,000, which is less than the carryforward. The saving is $280,000 x 21% = $58,800.","Applies 80% to the size of the loss rather than to taxable income.","Assumes the loss can offset all taxable income. The deduction is limited to 80% of taxable income.","Assumes the entire loss is used in one year."],"wt":["","concept","limit","limit"],"tags":{"area":"III","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The NOL deduction for post-2020 losses is limited to 80% of taxable income computed before the deduction.","from":"2026-01-01","calc":1,"steps":["Deduction = lesser of 400,000 and 80% x 350,000 = $280,000","Saving = $280,000 x 21% = $58,800"]}},{"i":"TCP-III-A-0007","t":"Ridge Top Corp. has a net capital loss carryover of $90,000 from 2026. It expects to recognize a $60,000 net capital gain in 2027 and has no other capital transactions. The corporate rate is 21%. What tax saving does the carryover produce in 2027?","mc":{"s":"Ridge Top Corp. has a net capital loss carryover of $90,000 from 2026. It expects to recognize a $60,000 net capital gain in 2027 and has no other capital transactions. The corporate rate is 21%. What tax saving does the carryover produce in 2027?","d":"","o":["$12,600","$18,900","$31,500","$60,000"],"a":1,"cite":"IRC §1212(a)(1); IRC §1211(a); IRC §11(b)","rat":"A corporate capital loss carryover offsets only capital gains.","ex":["A corporate capital loss carryover offsets only capital gains. It absorbs the $60,000 gain, saving 21% x $60,000 = $12,600; the remaining $30,000 carries forward.","Assumes the entire carryover can be used in 2027. It can offset only the capital gain available.","Adds the loss and the gain together.","Reports the gain absorbed rather than the tax saved."],"wt":["","limit","calc","trap"],"tags":{"area":"III","group":"A","skill":"Application","diff":1},"asof":"2026-09-29","rl":"A corporation's capital loss carryover reduces tax only to the extent of capital gains in the carryover year.","from":"2026-01-01","calc":1,"steps":["Loss absorbed = lesser of 90,000 and 60,000 = 60,000","Saving = 60,000 x 21% = $12,600"]}}],"5":[{"i":"TCP-III-A-0005","t":"Pine Point Co. has $1,000,000 of taxable income and plans a new plant. In State M, which apportions by an equally weighted three-factor formula (property, payroll, sales), the plant would give the company 40% of its property, 40% of its payroll and 10% of its sales. In State N, which apportions by sales only, the company would have 10% of its sales. Both states tax apportioned income at 7%. By how much is the tax in State M more than the tax in State N?","mc":{"s":"Pine Point Co. has $1,000,000 of taxable income and plans a new plant. In State M, which apportions by an equally weighted three-factor formula (property, payroll, sales), the plant would give the company 40% of its property, 40% of its payroll and 10% of its sales. In State N, which apportions by sales only, the company would have 10% of its sales. Both states tax apportioned income at 7%. By how much is the tax in State M more than the tax in State N?","d":"","o":["$7,000","$14,000","$21,000","$28,000"],"a":2,"cite":"Multistate Tax Compact art. IV; IRC §164(a)(3); Pub 535","rat":"State M's factor is (40% + 40% + 10%)/3 = 30%, so tax = $1,000,000 x 30% x 7% = $21,000.","ex":["This is the tax in State N, not the difference.","State M's factor is (40% + 40% + 10%)/3 = 30%, so tax = $1,000,000 x 30% x 7% = $21,000. State N's factor is 10%, so tax = $7,000. The difference is $14,000.","This is the tax in State M, not the difference.","Uses only the property factor for State M instead of the average of the three factors."],"wt":["trap","","trap","concept"],"tags":{"area":"III","group":"A","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Apportionment formulas that weight property and payroll increase the tax of a company that builds facilities in the state; a sales-only formula does not.","from":"2026-01-01","calc":1,"steps":["M factor = (0.40 + 0.40 + 0.10)/3 = 30%; tax = $21,000","N factor = 10%; tax = $7,000","Difference = $14,000"]}},{"i":"TCP-III-A-0006","t":"Dee Parker is a partner in a partnership doing business in a state that offers an elective pass-through entity tax with a full credit to partners. Dee's federal deduction for state and local taxes is limited to $10,000 because of her income, and she already pays $20,000 of state and local property tax individually. The partnership could elect to pay $60,000 of state income tax at the entity level on Dee's share, deducting it in computing partnership income. Dee's federal rate is 37%. By how much does the election reduce Dee's federal income tax?","mc":{"s":"Dee Parker is a partner in a partnership doing business in a state that offers an elective pass-through entity tax with a full credit to partners. Dee's federal deduction for state and local taxes is limited to $10,000 because of her income, and she already pays $20,000 of state and local property tax individually. The partnership could elect to pay $60,000 of state income tax at the entity level on Dee's share, deducting it in computing partnership income. Dee's federal rate is 37%. By how much does the election reduce Dee's federal income tax?","d":"","o":["$0","$3,700","$22,200","$60,000"],"a":3,"cite":"Notice 2020-75; IRC §164(b)(6); IRC §703(a)","rat":"Without the election, Dee's individual payment would be nondeductible because her deduction limit is already used by her property tax.","ex":["Assumes the entity-level payment is treated the same as an individual payment subject to the limit. The entity deduction is not subject to the individual limit.","Applies the individual limit of $10,000. The entity-level tax is deducted in full in computing partnership income.","Without the election, Dee's individual payment would be nondeductible because her deduction limit is already used by her property tax. With the election the partnership deducts $60,000 in computing income, reducing her share of income by $60,000 and her federal tax by $60,000 x 37% = $22,200.","Reports the amount of the tax deducted rather than the tax it saves."],"wt":["concept","limit","","trap"],"tags":{"area":"III","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"An entity-level state tax paid by a partnership is deducted in computing partnership income and is not subject to the individual limit on state and local taxes.","from":"2026-07-01","calc":1,"steps":["Entity-level deduction = 60,000","Federal saving = 60,000 x 37% = $22,200"]}}],"6":[{"i":"TCP-III-B-0001","t":"Assume for this question that Congress has enacted a corporate income tax rate of 25% for 2027, while the 2026 rate is 21%. Delta Street Corp., an accrual-basis C corporation, can choose to recognize $400,000 of income in 2026 by completing a sale before year end instead of in 2027, and can delay $150,000 of deductible expenses from December 2026 into January 2027. Ignoring the time value of money, what is the total federal tax effect of doing both, compared with taking no action?","mc":{"s":"Assume for this question that Congress has enacted a corporate income tax rate of 25% for 2027, while the 2026 rate is 21%. Delta Street Corp., an accrual-basis C corporation, can choose to recognize $400,000 of income in 2026 by completing a sale before year end instead of in 2027, and can delay $150,000 of deductible expenses from December 2026 into January 2027. Ignoring the time value of money, what is the total federal tax effect of doing both, compared with taking no action?","d":"","o":["$6,000","$10,000","$16,000","$22,000"],"a":4,"cite":"IRC §451; IRC §461; IRC §11(b)","rat":"Recognizing $400,000 of income in 2026 at 21% instead of 2027 at 25% saves $16,000.","ex":["Counts only the delayed deductions.","Subtracts the deduction effect. Moving deductions to the higher-rate year adds to the saving.","Counts only the accelerated income.","Recognizing $400,000 of income in 2026 at 21% instead of 2027 at 25% saves $16,000. Delaying $150,000 of deductions into 2027, when each dollar of deduction is worth 25% instead of 21%, saves $6,000. Total $22,000."],"wt":["calc","concept","calc",""],"tags":{"area":"III","group":"B","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"When rates will rise, accelerate income into the lower-rate year and delay deductions into the higher-rate year.","from":"2026-01-01","calc":1,"steps":["Income: 400,000 x (25% - 21%) = $16,000","Deductions: 150,000 x (25% - 21%) = $6,000","Total = $22,000"]}},{"i":"TCP-III-B-0004","t":"Copper Field Corp., an accrual-basis calendar-year C corporation, has a fixed obligation for year-end bonuses at December 31, 2026, and wants deductions in 2026. Which bonus is deductible in 2026?","mc":{"s":"Copper Field Corp., an accrual-basis calendar-year C corporation, has a fixed obligation for year-end bonuses at December 31, 2026, and wants deductions in 2026. Which bonus is deductible in 2026?","d":"","o":["A bonus owed to non-owner employees on December 31 and paid on March 1, 2027","A bonus owed to the corporation's 60% shareholder-employee on December 31 and paid on March 1, 2027","A bonus owed to non-owner employees on December 31 and paid on April 20, 2027","A bonus payable to non-owner employees only if they remain employed on the payment date in 2027"],"a":1,"cite":"IRC §404(a)(5); IRC §267(a)(2); Reg. §1.404(b)-1T","rat":"An accrued compensation liability that is fixed at year end and paid within 2 1/2 months after year end is deductible in the year accrued.","ex":["An accrued compensation liability that is fixed at year end and paid within 2 1/2 months after year end is deductible in the year accrued.","Amounts owed to a more-than-50% owner are deductible only when paid, because of the related-party rules.","Payment after the 2 1/2 month period defers the deduction to the year of payment.","A liability that depends on later employment is not fixed at year end."],"wt":["","concept","limit","concept"],"tags":{"area":"III","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"An accrual-basis corporation deducts a fixed bonus liability to non-owner employees in the year accrued if paid within 2 1/2 months; owner-related amounts wait for payment.","from":"2026-01-01"}}],"7":[{"i":"TCP-III-B-0002","t":"Bramble Corp., a calendar-year C corporation, had taxable income of $2,000,000 in 2024 and total tax of $420,000 for 2025. It expects total tax of $630,000 for 2026. What is the smallest first installment of 2026 estimated tax (due April 15) that avoids the underpayment penalty, without using the annualized income installment method?","mc":{"s":"Bramble Corp., a calendar-year C corporation, had taxable income of $2,000,000 in 2024 and total tax of $420,000 for 2025. It expects total tax of $630,000 for 2026. What is the smallest first installment of 2026 estimated tax (due April 15) that avoids the underpayment penalty, without using the annualized income installment method?","d":"","o":["$105,000","$141,750","$157,500","$420,000"],"a":1,"cite":"IRC §6655(d)(1); IRC §6655(d)(2); IRC §6655(g)(2)","rat":"Bramble is a large corporation because its taxable income was at least $1,000,000 in a preceding year, so it may use 100% of prior-year tax only for the first installment: 25% x $420,000 = $105,000.","ex":["Bramble is a large corporation because its taxable income was at least $1,000,000 in a preceding year, so it may use 100% of prior-year tax only for the first installment: 25% x $420,000 = $105,000. Later installments must catch up to 100% of current-year tax.","Uses 90% of current-year tax. The required annual payment for a corporation is 100% of current-year tax.","Uses 100% of current-year tax for the first installment. A large corporation may use prior-year tax for that installment.","Uses the whole prior-year tax as the first installment instead of one quarter of it."],"wt":["","limit","concept","calc"],"tags":{"area":"III","group":"B","skill":"Application","diff":3},"asof":"2026-09-29","rl":"A large corporation may base only its first installment on prior-year tax; the rest must be based on current-year tax.","from":"2026-01-01","calc":1,"steps":["Large corporation (taxable income of at least $1,000,000 in a preceding year)","First installment = 25% x 420,000 = $105,000"]}},{"i":"TCP-III-B-0005","t":"Sable Hollow Corp., a calendar-year C corporation, has never had taxable income above $1,000,000. Its 2025 tax was $80,000 and it expects a 2026 tax of $200,000. It wants to make four equal installments that are just enough to avoid the underpayment penalty and does not use the annualized method. What is each installment?","mc":{"s":"Sable Hollow Corp., a calendar-year C corporation, has never had taxable income above $1,000,000. Its 2025 tax was $80,000 and it expects a 2026 tax of $200,000. It wants to make four equal installments that are just enough to avoid the underpayment penalty and does not use the annualized method. What is each installment?","d":"","o":["$20,000","$45,000","$50,000","$80,000"],"a":1,"cite":"IRC §6655(d)(1); IRC §6655(d)(2); Form 1120-W instructions","rat":"The required annual payment is the lesser of 100% of current-year tax ($200,000) or 100% of prior-year tax ($80,000), so $80,000.","ex":["The required annual payment is the lesser of 100% of current-year tax ($200,000) or 100% of prior-year tax ($80,000), so $80,000. Four equal installments are $20,000 each.","Uses 90% of current-year tax. The corporate rate is 100%, and prior-year tax is smaller anyway.","Uses 100% of current-year tax, which is more than needed.","Treats the whole prior-year tax as one installment."],"wt":["","limit","concept","calc"],"tags":{"area":"III","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A corporation that is not large may base its installments on 100% of prior-year tax if that is less than 100% of current-year tax.","from":"2026-01-01","calc":1,"steps":["Required annual payment = lesser of 200,000 and 80,000 = 80,000","Each installment = 80,000 / 4 = $20,000"]}}],"8":[{"i":"TCP-III-B-0003","t":"Kira Volkov plans to transfer land with a basis of $100,000 and a fair market value of $400,000, subject to a $150,000 mortgage, to a new corporation in exchange for stock worth $200,000 and a $50,000 note from the corporation. The corporation will assume the mortgage. She will own all of the stock. What will the corporation's basis in the land be?","mc":{"s":"Kira Volkov plans to transfer land with a basis of $100,000 and a fair market value of $400,000, subject to a $150,000 mortgage, to a new corporation in exchange for stock worth $200,000 and a $50,000 note from the corporation. The corporation will assume the mortgage. She will own all of the stock. What will the corporation's basis in the land be?","d":"","o":["$100,000","$150,000","$200,000","$400,000"],"a":3,"cite":"IRC §351(b); IRC §357(c); IRC §362(a)","rat":"Kira recognizes gain equal to the boot ($50,000 note) plus liabilities assumed in excess of basis ($150,000 - $100,000 = $50,000): $100,000.","ex":["Uses only her basis. The corporation adds the gain she recognizes.","Adds only the note as recognized gain and misses the gain from liabilities in excess of basis.","Kira recognizes gain equal to the boot ($50,000 note) plus liabilities assumed in excess of basis ($150,000 - $100,000 = $50,000): $100,000. The corporation's basis is her basis plus the gain recognized: $100,000 + $100,000 = $200,000.","Uses fair market value, which applies only in a taxable exchange."],"wt":["concept","concept","","concept"],"tags":{"area":"III","group":"B","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"In a section 351 exchange with boot and liabilities in excess of basis, the corporation's basis equals the transferor's basis plus gain recognized.","from":"2026-01-01","calc":1,"steps":["Boot = 50,000","Liabilities over basis = 150,000 - 100,000 = $50,000","Gain recognized = $100,000; corporation's basis = 100,000 + $100,000 = $200,000"]}},{"i":"TCP-III-B-0006","t":"Dana Wolfe transfers equipment with an adjusted basis of $200,000 and a fair market value of $120,000 to a newly formed corporation in exchange for all of its stock. No election is made to reduce her stock basis. What is Dana's basis in the stock?","mc":{"s":"Dana Wolfe transfers equipment with an adjusted basis of $200,000 and a fair market value of $120,000 to a newly formed corporation in exchange for all of its stock. No election is made to reduce her stock basis. What is Dana's basis in the stock?","d":"","o":["$80,000","$120,000","$200,000","$320,000"],"a":3,"cite":"IRC §362(e)(2)(A); IRC §358(a); IRC §351(a)","rat":"The transfer qualifies under the control rules, so her stock basis is her carryover basis, $200,000.","ex":["Uses the built-in loss amount rather than a basis.","Uses fair market value for her stock basis. Her stock basis carries over; it is the corporation's asset basis that is limited to value.","The transfer qualifies under the control rules, so her stock basis is her carryover basis, $200,000. Because the property has a net built-in loss, the corporation's basis in the equipment is reduced to fair market value ($120,000), so the loss is preserved only in the shareholder's stock basis.","Adds the basis and the fair market value."],"wt":["trap","concept","","calc"],"tags":{"area":"III","group":"B","skill":"Application","diff":3},"asof":"2026-09-29","rl":"When a transferor contributes built-in loss property in a section 351 exchange, the corporation's basis is limited to fair market value unless the transferor elects to reduce stock basis instead.","from":"2026-01-01","calc":1,"steps":["Stock basis = carryover basis = 200,000","Corporation's basis = lesser of 200,000 and 120,000 = 120,000 (no election)"]}},{"i":"TCP-III-B-0007","t":"Orion Corp., a C corporation taxed at 21%, will pay its sole owner-employee $100,000 of its current pre-tax earnings, and the corporation's total cash cost is the same $100,000 either way. Option 1: pay a deductible bonus, where the corporation's cost includes its share of Medicare tax. Option 2: pay a dividend out of the earnings after corporate tax. The owner's ordinary rate is 37%. Qualified dividends are taxed at 20% plus a 3.8% net investment income tax. Medicare tax on wages is 1.45% for the employer and 1.45% for the employee, plus 0.9% additional Medicare tax on the employee; Social Security tax does not apply because the wage base is already exceeded. Which option produces less combined corporate and owner federal tax, and by how much?","mc":{"s":"Orion Corp., a C corporation taxed at 21%, will pay its sole owner-employee $100,000 of its current pre-tax earnings, and the corporation's total cash cost is the same $100,000 either way. Option 1: pay a deductible bonus, where the corporation's cost includes its share of Medicare tax. Option 2: pay a dividend out of the earnings after corporate tax. The owner's ordinary rate is 37%. Qualified dividends are taxed at 20% plus a 3.8% net investment income tax. Medicare tax on wages is 1.45% for the employer and 1.45% for the employee, plus 0.9% additional Medicare tax on the employee; Social Security tax does not apply because the wage base is already exceeded. Which option produces less combined corporate and owner federal tax, and by how much?","d":"","o":["The bonus, by about $452","The bonus, by about $2,802","The dividend, by about $3,417","The dividend, by about $415"],"a":4,"cite":"IRC §162(a)(1); IRC §3101(b); IRC §1411; IRC §1(h)(11)","rat":"Bonus: $100,000 of cost covers a $98,571 bonus and $1,429 of employer Medicare; the owner pays 37% + 1.45% + 0.9% = 39.35% on the bonus, $38,788, so total tax is $40,217.","ex":["Leaves out the employer's Medicare tax on the bonus, which is part of the $100,000 cost. That makes the bonus look cheaper than it is.","Counts only income tax at 37% on the bonus. Medicare tax on wages, including the 0.9% additional tax, is a real cost of the bonus.","Leaves out the 3.8% net investment income tax on the dividend, making the dividend look cheaper than it is.","Bonus: $100,000 of cost covers a $98,571 bonus and $1,429 of employer Medicare; the owner pays 37% + 1.45% + 0.9% = 39.35% on the bonus, $38,788, so total tax is $40,217. Dividend: corporate tax $21,000 plus 23.8% on the remaining $79,000 ($18,802), or $39,802. The dividend costs about $415 less."],"wt":["calc","trap","trap",""],"tags":{"area":"III","group":"B","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Compensation is deductible but bears payroll tax, while a dividend from a C corporation is taxed at the corporate level and then to the shareholder, so the two can cost nearly the same and payroll tax details matter.","from":"2026-01-01","calc":1,"steps":["Bonus B: B + 1.45% x B = 100,000, so B = 98,571 and employer Medicare = 1,429","Owner tax on bonus = 98,571 x (37% + 1.45% + 0.9%) = 38,788; total tax = 38,788 + 1,430 = 40,217","Dividend: corporate tax = 100,000 x 21% = 21,000; dividend = 79,000; owner tax = 79,000 x 23.8% = 18,802; total = 39,802","The dividend is about 415 lower"]}}],"9":[{"i":"TCP-III-C-0001","t":"Umber Creek, Inc., a calendar-year corporation, was a C corporation until it elected S status effective January 1, 2022. Assume its taxable income (as if it were a C corporation) is more than large enough that the taxable income limit does not apply, and that its net unrealized built-in gain does not limit the tax. In 2026 it sells a building for $520,000. On January 1, 2022 the building was worth $400,000 and its adjusted basis was $150,000, which is still its basis. The corporate rate is 21%. What is the corporation's built-in gains tax on the sale?","mc":{"s":"Umber Creek, Inc., a calendar-year corporation, was a C corporation until it elected S status effective January 1, 2022. Assume its taxable income (as if it were a C corporation) is more than large enough that the taxable income limit does not apply, and that its net unrealized built-in gain does not limit the tax. In 2026 it sells a building for $520,000. On January 1, 2022 the building was worth $400,000 and its adjusted basis was $150,000, which is still its basis. The corporate rate is 21%. What is the corporation's built-in gains tax on the sale?","d":"","o":["$0","$25,200","$52,500","$77,700"],"a":3,"cite":"IRC §1374(a); IRC §1374(d)(7); IRC §1374(b)(1)","rat":"The 2026 sale is in the five-year recognition period.","ex":["Assumes the recognition period has ended. The period is five years from the first S corporation year, which includes 2026.","Taxes only the post-conversion appreciation, which is the amount that is not built-in gain.","The 2026 sale is in the five-year recognition period. The gain is $520,000 - $150,000 = $370,000, but only the built-in gain at conversion, $400,000 - $150,000 = $250,000, is taxed at 21%: $52,500.","Taxes the whole gain. Appreciation after conversion is not built-in gain."],"wt":["limit","concept","","concept"],"tags":{"area":"III","group":"C","skill":"Application","diff":3},"asof":"2026-09-29","rl":"Built-in gains tax applies at the corporate rate to gain recognized during the five-year recognition period, limited to the built-in gain at conversion.","from":"2026-01-01","calc":1,"steps":["Built-in gain at conversion = 400,000 - 150,000 = $250,000","Recognized built-in gain = lesser of total gain $370,000 and $250,000","Tax = 21% x $250,000 = $52,500"]}},{"i":"TCP-III-C-0002","t":"Jasper Lane, Inc. converted from a C corporation to an S corporation on January 1, 2022. In December 2026 it plans to sell an asset with $180,000 of built-in gain. Its 2026 taxable income, computed as if it were a C corporation and including this sale, is $120,000. The corporate rate is 21% and its net unrealized built-in gain at conversion is not a limit. What built-in gains tax does the sale produce?","mc":{"s":"Jasper Lane, Inc. converted from a C corporation to an S corporation on January 1, 2022. In December 2026 it plans to sell an asset with $180,000 of built-in gain. Its 2026 taxable income, computed as if it were a C corporation and including this sale, is $120,000. The corporate rate is 21% and its net unrealized built-in gain at conversion is not a limit. What built-in gains tax does the sale produce?","d":"","o":["$0","$12,600","$25,200","$37,800"],"a":3,"cite":"IRC §1374(d)(2); IRC §1374(d)(7); IRC §1374(b)","rat":"The net recognized built-in gain is limited to the corporation's taxable income computed as if it were a C corporation.","ex":["Assumes the recognition period has ended. December 2026 is still within the five-year period.","Applies the tax to the built-in gain in excess of taxable income.","The net recognized built-in gain is limited to the corporation's taxable income computed as if it were a C corporation. The lesser of $180,000 and $120,000 is $120,000; the tax is 21% x $120,000 = $25,200.","Ignores the taxable income limit on net recognized built-in gain."],"wt":["limit","concept","","limit"],"tags":{"area":"III","group":"C","skill":"Application","diff":3},"asof":"2026-09-29","rl":"Net recognized built-in gain is limited to taxable income computed as if the corporation were a C corporation.","from":"2026-01-01","calc":1,"steps":["Net recognized built-in gain = lesser of 180,000 and 120,000 = $120,000","Tax = 21% x $120,000 = $25,200"]}}],"10":[{"i":"TCP-III-C-0003","t":"Vantage Mills, Inc., an S corporation, earned ordinary income of $730,000 evenly through 2026. On October 1, 2026, an entity that is not an eligible shareholder acquired shares, terminating the S election on that date. The corporation makes no election to close its books, and there are 92 days in the C corporation short year (October 1 through December 31). The corporate rate is 21%. What is the corporation's tax for the C corporation short year?","mc":{"s":"Vantage Mills, Inc., an S corporation, earned ordinary income of $730,000 evenly through 2026. On October 1, 2026, an entity that is not an eligible shareholder acquired shares, terminating the S election on that date. The corporation makes no election to close its books, and there are 92 days in the C corporation short year (October 1 through December 31). The corporate rate is 21%. What is the corporation's tax for the C corporation short year?","d":"","o":["$38,640","$76,650","$114,660","$153,300"],"a":1,"cite":"IRC §1362(e)(1); IRC §1362(e)(2); IRC §11(b)","rat":"Without a closing election the year's income is allocated by days: $730,000 x 92/365 = $184,000 to the C short year.","ex":["Without a closing election the year's income is allocated by days: $730,000 x 92/365 = $184,000 to the C short year. Tax = 21% x $184,000 = $38,640.","Uses half of the year rather than the actual days.","Taxes the S short year's share, which stays in the S corporation year.","Taxes the whole year as C corporation income. Only the days after termination are in the C short year."],"wt":["","calc","concept","concept"],"tags":{"area":"III","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"When an S election terminates mid-year, income is allocated between the S and C short years by days unless the corporation elects to close its books.","from":"2026-01-01","calc":1,"steps":["C short-year days = 92; income allocated = 730,000 x 92/365 = $184,000","Tax = 21% x $184,000 = $38,640"]}},{"i":"TCP-III-C-0004","t":"Halden Print, Inc. has been an S corporation for many years. On March 3, 2026, a shareholder transferred shares to an ineligible shareholder, which terminated the S election, and the corporation does not qualify for or seek inadvertent termination relief. Which statement about the consequences is correct?","mc":{"s":"Halden Print, Inc. has been an S corporation for many years. On March 3, 2026, a shareholder transferred shares to an ineligible shareholder, which terminated the S election, and the corporation does not qualify for or seek inadvertent termination relief. Which statement about the consequences is correct?","d":"","o":["The corporation may immediately re-elect S status by filing Form 2553 for the same year","It becomes a C corporation on March 3 and cannot re-elect S status for five years without IRS consent","The election terminates at the beginning of 2026, so the corporation is a C corporation for the whole year","The shareholders recognize gain on their stock as if the corporation liquidated when it becomes a C corporation"],"a":2,"cite":"IRC §1362(d)(2); IRC §1362(g); IRC §1362(f)","rat":"A termination takes effect on the date of the terminating event, and a corporation whose election terminated must wait five years to re-elect unless the IRS consents.","ex":["There is a five-year waiting period after a termination, absent IRS consent.","A termination takes effect on the date of the terminating event, and a corporation whose election terminated must wait five years to re-elect unless the IRS consents.","The termination is effective on the date of the terminating event, so the year is split.","A termination by an ineligible shareholder is not a liquidation; the corporation continues as a C corporation."],"wt":["limit","","concept","concept"],"tags":{"area":"III","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"An S election terminates on the day of the terminating event; the corporation generally waits five years to re-elect unless the IRS consents.","from":"2026-01-01"}},{"i":"TCP-III-C-0008","t":"Sal Reed owns all of Reed Mills, Inc., an S corporation since its formation, with stock basis of $200,000 that equals the net basis of its assets. The corporation has no liabilities. A corporate buyer will pay $1,000,000 for all of the stock in a purchase that qualifies for a joint election that treats the purchase as a sale of the corporation's assets followed by a liquidation, and the buyer is willing to make it. The assets are worth $1,000,000. Of the $800,000 total gain, $150,000 would be ordinary income from depreciation recapture and the rest long-term capital gain. Sal's rates are 37% on ordinary income and 20% on long-term capital gain. How much more federal income tax does Sal pay if the election is made?","mc":{"s":"Sal Reed owns all of Reed Mills, Inc., an S corporation since its formation, with stock basis of $200,000 that equals the net basis of its assets. The corporation has no liabilities. A corporate buyer will pay $1,000,000 for all of the stock in a purchase that qualifies for a joint election that treats the purchase as a sale of the corporation's assets followed by a liquidation, and the buyer is willing to make it. The assets are worth $1,000,000. Of the $800,000 total gain, $150,000 would be ordinary income from depreciation recapture and the rest long-term capital gain. Sal's rates are 37% on ordinary income and 20% on long-term capital gain. How much more federal income tax does Sal pay if the election is made?","d":"","o":["$25,500","$30,000","$55,500","$185,500"],"a":1,"cite":"IRC §338(h)(10); IRC §1245(a); IRC §1366(a); IRC §331(a)","rat":"Without the election, the sale is a $800,000 capital gain on stock, taxed at 20% ($160,000).","ex":["Without the election, the sale is a $800,000 capital gain on stock, taxed at 20% ($160,000). With it, the S corporation's deemed asset sale passes through $150,000 of ordinary income and $650,000 of capital gain ($55,500 + $130,000 = $185,500), and the deemed liquidation adds no more gain because his basis rose by $800,000. The extra tax is $25,500.","Taxes the recapture at only 20%. The extra cost is the 17-point rate difference on the $150,000, or $25,500.","This is the whole tax on the recapture, not the extra tax. The same $150,000 would otherwise be taxed at 20% as part of the stock gain.","This is Sal's total tax with the election. The question asks for the increase over the $160,000 stock sale tax."],"wt":["","calc","trap","trap"],"tags":{"area":"III","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"An election to treat a stock sale as an asset sale passes the corporation's ordinary income items to the S shareholders, so the shareholder can pay more tax even though the total gain is unchanged.","from":"2026-01-01","calc":1,"steps":["Stock sale: gain = 1,000,000 - 200,000 = 800,000 at 20% = 160,000","Election: pass-through of 150,000 ordinary (37% = 55,500) and 650,000 capital gain (20% = 130,000) = 185,500; deemed liquidation: basis 200,000 + 800,000 = 1,000,000, no further gain","Extra tax = 185,500 - 160,000 = 25,500"]}}],"11":[{"i":"TCP-III-C-0005","t":"Zack Moore lent his S corporation $60,000 under a written note. Earlier losses reduced his basis in the note to $20,000. During 2026 the corporation had net income items that produce a $15,000 net increase in his basis, and at year end it repays $30,000 of the note. What gain does Zack recognize on the repayment?","mc":{"s":"Zack Moore lent his S corporation $60,000 under a written note. Earlier losses reduced his basis in the note to $20,000. During 2026 the corporation had net income items that produce a $15,000 net increase in his basis, and at year end it repays $30,000 of the note. What gain does Zack recognize on the repayment?","d":"","o":["$0","$12,500","$20,000","$30,000"],"a":2,"cite":"IRC §1367(b)(2); Reg. §1.1367-2(c); Reg. §1.1367-2(e)","rat":"The net increase for the year first restores debt basis: $20,000 + $15,000 = $35,000.","ex":["Assumes the repayment is less than the restored basis, so no gain arises. Gain arises in proportion to the basis shortfall relative to face.","The net increase for the year first restores debt basis: $20,000 + $15,000 = $35,000. The note is now $25,000 below face, and that shortfall is the share of each repayment that is gain: $30,000 x ($25,000/$60,000) = $12,500.","Ignores the restoration of debt basis from the year's net increase.","Treats the entire repayment as gain instead of only the proportion above basis."],"wt":["concept","","concept","concept"],"tags":{"area":"III","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Repayment of a shareholder note with reduced basis produces gain in proportion to the basis shortfall, after basis is restored by the year's net increase.","from":"2026-01-01","calc":1,"steps":["Restored basis = 20,000 + 15,000 = $35,000","Gain fraction = (60,000 - $35,000) / 60,000","Gain = 30,000 x that fraction = $12,500"]}},{"i":"TCP-III-C-0007","t":"Gale Force Inc. is an S corporation. Its sole shareholder is selling all of the stock for a total gain of $500,000, which equals the gain that the corporation would realize on a sale of its assets. If a joint election is made to treat the sale as a sale of assets followed by a liquidation, $100,000 of the gain is depreciation recapture taxed as ordinary income at 37% and $400,000 is capital gain taxed at 20%. Without the election the whole gain is capital gain at 20%. Ignore all other taxes. How much more tax does the shareholder pay if the election is made?","mc":{"s":"Gale Force Inc. is an S corporation. Its sole shareholder is selling all of the stock for a total gain of $500,000, which equals the gain that the corporation would realize on a sale of its assets. If a joint election is made to treat the sale as a sale of assets followed by a liquidation, $100,000 of the gain is depreciation recapture taxed as ordinary income at 37% and $400,000 is capital gain taxed at 20%. Without the election the whole gain is capital gain at 20%. Ignore all other taxes. How much more tax does the shareholder pay if the election is made?","d":"","o":["$17,000","$37,000","$100,000","$117,000"],"a":1,"cite":"IRC §338(h)(10); IRC §1245; IRC §1(h)","rat":"With the election: $100,000 x 37% + $400,000 x 20% = $117,000.","ex":["With the election: $100,000 x 37% + $400,000 x 20% = $117,000. Without it: $500,000 x 20% = $100,000. The election costs $17,000, a price the buyer pays for the stepped-up asset basis.","Counts only the tax on the ordinary income, not the difference from the capital gain rate.","This is the total tax without the election, not the additional tax.","This is the total tax with the election, not the additional tax."],"wt":["","concept","trap","trap"],"tags":{"area":"III","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A joint election to treat a stock sale as an asset sale exposes the seller to ordinary income on recapture and similar assets.","from":"2026-01-01","calc":1,"steps":["Election: $37,000 + $80,000 = $117,000","No election: $100,000","Extra tax = $17,000"]}},{"i":"TCP-III-C-0009","t":"Leah Voss, single, owns all of an S corporation that will earn $300,000 in 2026 before any salary to her and before employer payroll tax. She can defend either of two salaries as reasonable: $60,000 or $120,000. Assume Social Security and Medicare tax total 7.65% for the employer and 7.65% for the employee on wages (both salaries are below the Social Security wage base), her ordinary rate is 35%, and the corporation's remaining income passes through to her. Her taxable income is high enough that the wage limit on the 20% qualified business income deduction applies in full, so that deduction is limited to 50% of the W-2 wages paid. Ignore state taxes and additional Medicare tax. How much more after-tax cash does Leah keep with the $60,000 salary than with the $120,000 salary?","mc":{"s":"Leah Voss, single, owns all of an S corporation that will earn $300,000 in 2026 before any salary to her and before employer payroll tax. She can defend either of two salaries as reasonable: $60,000 or $120,000. Assume Social Security and Medicare tax total 7.65% for the employer and 7.65% for the employee on wages (both salaries are below the Social Security wage base), her ordinary rate is 35%, and the corporation's remaining income passes through to her. Her taxable income is high enough that the wage limit on the 20% qualified business income deduction applies in full, so that deduction is limited to 50% of the W-2 wages paid. Ignore state taxes and additional Medicare tax. How much more after-tax cash does Leah keep with the $60,000 salary than with the $120,000 salary?","d":"","o":["$6,116","$7,574","$9,180","$12,095"],"a":1,"cite":"IRC §199A(b)(2); IRC §3121(a); Rev. Rul. 74-44","rat":"With $60,000 of wages: employer tax $4,590, S income $235,410, deduction limited to $30,000 (50% of wages), taxable income $265,410, tax $92,894, after-tax cash $197,927.","ex":["With $60,000 of wages: employer tax $4,590, S income $235,410, deduction limited to $30,000 (50% of wages), taxable income $265,410, tax $92,894, after-tax cash $197,927. With $120,000: employer tax $9,180, S income $170,820, deduction $34,164, taxable income $256,656, tax $89,830, after-tax cash $191,810. The lower salary keeps $6,116 more.","Leaves out the qualified business income deduction. It is not the same under both salaries, so the payroll savings from the lower salary are partly offset by the wage limit.","This is only the extra payroll tax from the higher salary. The lower salary also loses part of the deduction and pushes more income into the 35% bracket, so the net benefit is smaller.","Ignores the wage limit and gives the full 20% deduction under both salaries. At $60,000 of wages the deduction is limited to $30,000, which reduces the benefit of the low salary."],"wt":["","trap","calc","concept"],"tags":{"area":"III","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A lower S corporation salary saves payroll tax but also reduces the wages that support the qualified business income deduction, so the two effects must be netted.","from":"2026-07-01","calc":1,"steps":["Salary 60,000: employer tax = 4,590; S income = 300,000 - 60,000 - 4,590 = 235,410; deduction = min(47,082, 30,000) = 30,000; taxable = 265,410; tax = 92,894; after-tax cash = 300,000 - 4,590 - 4,590 - 92,894 = 197,927","Salary 120,000: employer tax = 9,180; S income = 170,820; deduction = min(34,164, 60,000) = 34,164; taxable = 256,656; tax = 89,830; after-tax cash = 191,810","Difference = 197,927 - 191,810 = 6,116"]}}],"12":[{"i":"TCP-III-C-0006","t":"Fox Run, Inc. is an S corporation with an accumulated adjustments account of $40,000 and accumulated earnings and profits of $100,000. It will distribute $100,000 to its sole shareholder in 2026. Without any election, distributions come first from the accumulated adjustments account and then from accumulated earnings and profits. The corporation and shareholder consider electing to treat the distribution as coming first from accumulated earnings and profits. Dividends are taxed at 23.8% including the net investment income tax. How much additional tax does the election cause in 2026?","mc":{"s":"Fox Run, Inc. is an S corporation with an accumulated adjustments account of $40,000 and accumulated earnings and profits of $100,000. It will distribute $100,000 to its sole shareholder in 2026. Without any election, distributions come first from the accumulated adjustments account and then from accumulated earnings and profits. The corporation and shareholder consider electing to treat the distribution as coming first from accumulated earnings and profits. Dividends are taxed at 23.8% including the net investment income tax. How much additional tax does the election cause in 2026?","d":"","o":["$9,520","$14,280","$19,040","$23,800"],"a":1,"cite":"IRC §1368(e)(3); IRC §1368(c); IRC §1(h)(11)","rat":"Without the election, $40,000 is a tax-free return of basis and $60,000 is a dividend, taxed at 23.8% = $14,280.","ex":["Without the election, $40,000 is a tax-free return of basis and $60,000 is a dividend, taxed at 23.8% = $14,280. With the election the whole $100,000 is a dividend, $23,800. The additional tax is $9,520.","This is the tax without the election, not the additional tax.","Doubles the tax on the accumulated adjustments account amount.","This is the tax with the election, not the additional tax."],"wt":["","trap","calc","trap"],"tags":{"area":"III","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Electing to distribute accumulated E&P first converts what would be a tax-free return of basis into a dividend, but eliminates E&P.","from":"2026-01-01","calc":1,"steps":["No election: dividend = 100,000 - 40,000 = $60,000; tax $14,280","Election: dividend = 100,000; tax $23,800","Additional tax = $9,520"]}}],"13":[{"i":"TCP-III-D-0001","t":"Ira Bell contributes equipment with an adjusted basis of $200,000 and a fair market value of $120,000 to a partnership in which he and Mae share profits and losses equally. The partnership later sells the equipment for $100,000. How much of the tax loss on the sale is allocated to Ira?","mc":{"s":"Ira Bell contributes equipment with an adjusted basis of $200,000 and a fair market value of $120,000 to a partnership in which he and Mae share profits and losses equally. The partnership later sells the equipment for $100,000. How much of the tax loss on the sale is allocated to Ira?","d":"","o":["$50,000","$80,000","$90,000","$100,000"],"a":3,"cite":"IRC §704(c)(1)(C); IRC §704(c)(1)(A); Reg. §1.704-3","rat":"The built-in loss ($200,000 - $120,000 = $80,000) is allocated only to Ira.","ex":["Shares the whole loss equally and ignores that the built-in loss belongs to the contributor.","Allocates only the built-in loss and omits Ira's share of the later decline.","The built-in loss ($200,000 - $120,000 = $80,000) is allocated only to Ira. The additional loss after contribution ($120,000 - $100,000 = $20,000) is shared equally, so Ira gets $10,000. Total $90,000.","Allocates the entire loss to Ira."],"wt":["concept","calc","","concept"],"tags":{"area":"III","group":"D","skill":"Application","diff":3},"asof":"2026-09-29","rl":"Built-in loss on contributed property is taken into account only by the contributing partner; later declines are shared under the agreement.","from":"2026-01-01","calc":1,"steps":["Built-in loss = 200,000 - 120,000 = $80,000","Later decline = 120,000 - 100,000 = $20,000; Ira's half = $10,000","Total = $90,000"]}}],"14":[{"i":"TCP-III-D-0002","t":"Nell Pryor is a 25% partner in a partnership with $200,000 of ordinary income before any payment to her. The partners are deciding whether to pay her $60,000 for services as a guaranteed payment or as a nonliquidating cash distribution, which is within her basis. How much more income does Nell report with the guaranteed payment than with the distribution?","mc":{"s":"Nell Pryor is a 25% partner in a partnership with $200,000 of ordinary income before any payment to her. The partners are deciding whether to pay her $60,000 for services as a guaranteed payment or as a nonliquidating cash distribution, which is within her basis. How much more income does Nell report with the guaranteed payment than with the distribution?","d":"","o":["$15,000","$30,000","$35,000","$45,000"],"a":4,"cite":"IRC §707(c); IRC §731(a); IRC §702","rat":"With the guaranteed payment she reports $60,000 plus 25% of the $140,000 left after the deduction, $35,000, for $95,000.","ex":["Counts only her share of the deduction.","Uses half of the guaranteed payment.","Reports only her share of the income remaining after the deduction.","With the guaranteed payment she reports $60,000 plus 25% of the $140,000 left after the deduction, $35,000, for $95,000. With the distribution she reports 25% x $200,000 = $50,000, and the distribution is not income. The difference is $45,000."],"wt":["trap","calc","concept",""],"tags":{"area":"III","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A guaranteed payment is ordinary income to the partner and a deduction to the partnership; a nonliquidating distribution is generally not taxable within basis.","from":"2026-01-01","calc":1,"steps":["Guaranteed payment case = 60,000 + 25% x (200,000 - 60,000) = $95,000","Distribution case = 25% x 200,000 = $50,000","Difference = $45,000"]}},{"i":"TCP-III-D-0006","t":"Kai Alvarado, a calendar-year partner, receives guaranteed payments for services of $5,000 a month from a partnership whose valid fiscal year ends on June 30, 2027. He received $30,000 from July through December 2026 and $30,000 from January through June 2027. In which of his tax years does he report the $60,000?","mc":{"s":"Kai Alvarado, a calendar-year partner, receives guaranteed payments for services of $5,000 a month from a partnership whose valid fiscal year ends on June 30, 2027. He received $30,000 from July through December 2026 and $30,000 from January through June 2027. In which of his tax years does he report the $60,000?","d":"","o":["$30,000 in 2026 and $30,000 in 2027, because he reports each payment when he receives it","All $60,000 in 2026, because the first payment was received in that year","All $60,000 in 2027, because the partnership's year ends June 30, 2027","All $60,000 in 2028, when the partnership files its return for the year ended June 30, 2027"],"a":3,"cite":"IRC §706(a); IRC §707(c); Reg. §1.706-1(a)","rat":"A partner includes guaranteed payments and distributive share for the partnership year that ends within the partner's tax year.","ex":["Guaranteed payments are reported for the partnership year, not when each payment is received.","The partner reports for the partnership year that ends in his tax year, which is 2027.","A partner includes guaranteed payments and distributive share for the partnership year that ends within the partner's tax year.","Filing dates do not control. The partnership year ends June 30, 2027, so the payments belong in his 2027 year."],"wt":["concept","trap","","concept"],"tags":{"area":"III","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A partner reports items, including guaranteed payments, for the partnership year that ends with or within the partner's tax year.","from":"2026-01-01"}}],"15":[{"i":"TCP-III-D-0003","t":"Wes Adair contributes land with a basis of $100,000 and a fair market value of $400,000 to a partnership. On the same day the partnership pays him $150,000 in cash from its existing funds, not from borrowed money, and the payment is not explained by any exception. What gain does Wes recognize?","mc":{"s":"Wes Adair contributes land with a basis of $100,000 and a fair market value of $400,000 to a partnership. On the same day the partnership pays him $150,000 in cash from its existing funds, not from borrowed money, and the payment is not explained by any exception. What gain does Wes recognize?","d":"","o":["$0","$50,000","$75,000","$112,500"],"a":4,"cite":"IRC §707(a)(2)(B); Reg. §1.707-3; IRC §721(a)","rat":"A contribution followed closely by a payment to the contributor is a disguised sale of the part of the property equal to the payment ($150,000/$400,000 = 37.5%).","ex":["Assumes the contribution is entirely tax-free. A payment made in close connection with the contribution is treated as sale proceeds.","Subtracts the entire basis from the payment.","Recognizes only half of the payment as gain.","A contribution followed closely by a payment to the contributor is a disguised sale of the part of the property equal to the payment ($150,000/$400,000 = 37.5%). Basis allocated to the sale is $37,500, so gain = $150,000 - $37,500 = $112,500."],"wt":["concept","concept","calc",""],"tags":{"area":"III","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A payment to a contributing partner within two years is presumed to be a sale of part of the property, and gain is recognized on the part sold.","from":"2026-01-01","calc":1,"steps":["Portion sold = 150,000 / 400,000","Basis allocated = 150,000/400,000 x 100,000 = $37,500","Gain = 150,000 - $37,500 = $112,500"]}},{"i":"TCP-III-D-0004","t":"In 2023 Pia Doran contributed land with a basis of $50,000 and a fair market value of $200,000 to a partnership. In 2026, when the land is worth $260,000, the partnership distributes the land to another partner, Sam, in a nonliquidating distribution. Pia's interest continues. How much gain does Pia recognize because of the distribution?","mc":{"s":"In 2023 Pia Doran contributed land with a basis of $50,000 and a fair market value of $200,000 to a partnership. In 2026, when the land is worth $260,000, the partnership distributes the land to another partner, Sam, in a nonliquidating distribution. Pia's interest continues. How much gain does Pia recognize because of the distribution?","d":"","o":["$0","$60,000","$150,000","$210,000"],"a":3,"cite":"IRC §704(c)(1)(B); IRC §737; Reg. §1.704-4; Reg. §1.704-4(a)(1)","rat":"Distributing contributed property to another partner within seven years of the contribution causes the contributor to recognize the built-in gain at contribution, $200,000 - $50,000 = $150,000, as if the partnership had sold the property.","ex":["Assumes a distribution is never taxable to the contributor. The seven-year anti-shifting rule applies.","Uses only the post-contribution appreciation, which is not the built-in gain at contribution.","Distributing contributed property to another partner within seven years of the contribution causes the contributor to recognize the built-in gain at contribution, $200,000 - $50,000 = $150,000, as if the partnership had sold the property.","Uses the total appreciation since her original basis, including gain that arose after the contribution."],"wt":["concept","concept","","concept"],"tags":{"area":"III","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A contributing partner recognizes built-in gain when the partnership distributes the contributed property to another partner within seven years.","from":"2026-01-01","calc":1,"steps":["Built-in gain at contribution = 200,000 - 50,000 = $150,000"]}},{"i":"TCP-III-D-0005","t":"Ivy Reed contributes equipment with an adjusted basis of $200,000 and a fair market value of $120,000 to a partnership in which she and Hugo share profits and losses equally. The partnership sells the equipment for $150,000. Hugo's share is computed using a basis equal to the fair market value at contribution. How much tax loss on the sale is allocated to Ivy?","mc":{"s":"Ivy Reed contributes equipment with an adjusted basis of $200,000 and a fair market value of $120,000 to a partnership in which she and Hugo share profits and losses equally. The partnership sells the equipment for $150,000. Hugo's share is computed using a basis equal to the fair market value at contribution. How much tax loss on the sale is allocated to Ivy?","d":"","o":["$15,000","$50,000","$65,000","$80,000"],"a":3,"cite":"IRC §704(c)(1)(C); Reg. §1.704-3(a); IRC §721","rat":"The partnership's tax loss is $200,000 - $150,000 = $50,000.","ex":["This is Hugo's gain, not Ivy's loss.","Allocates the entire partnership loss to Ivy without offsetting Hugo's gain.","The partnership's tax loss is $200,000 - $150,000 = $50,000. For Hugo, the basis is treated as $120,000, so he has a gain of $150,000 - $120,000 = $30,000 and reports half, $15,000. The rest of the net loss goes to Ivy: $50,000 + $15,000 = $65,000.","Allocates only the built-in loss and ignores the sale price above fair market value."],"wt":["trap","concept","","concept"],"tags":{"area":"III","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"For built-in loss property, the other partners are allocated items as if the basis equaled fair market value at contribution.","from":"2026-01-01","calc":1,"steps":["Partnership loss = 200,000 - 150,000 = $50,000","Hugo's gain = 50% x (150,000 - 120,000) = $15,000","Ivy's loss = $50,000 + $15,000 = $65,000"]}},{"i":"TCP-III-D-0007","t":"Tom Baird is offered a 10% interest in Quill LLC, a partnership with no debt, for services and without a cash contribution. Plan 1: he receives a 10% capital interest, immediately vested, that would entitle him to $100,000 if the partnership liquidated on that day. Plan 2: he receives a 10% profits interest that would entitle him to nothing on an immediate liquidation, and it meets the safe harbor requirements. Three years later he sells his interest for $130,000. Assume his rate is 37% on ordinary income and 20% on long-term capital gain, no allocations of income occur, and ignore self-employment tax, the partnership's deduction, and other items. How much less total federal income tax does Tom pay under Plan 2 than under Plan 1 on the receipt and the sale together?","mc":{"s":"Tom Baird is offered a 10% interest in Quill LLC, a partnership with no debt, for services and without a cash contribution. Plan 1: he receives a 10% capital interest, immediately vested, that would entitle him to $100,000 if the partnership liquidated on that day. Plan 2: he receives a 10% profits interest that would entitle him to nothing on an immediate liquidation, and it meets the safe harbor requirements. Three years later he sells his interest for $130,000. Assume his rate is 37% on ordinary income and 20% on long-term capital gain, no allocations of income occur, and ignore self-employment tax, the partnership's deduction, and other items. How much less total federal income tax does Tom pay under Plan 2 than under Plan 1 on the receipt and the sale together?","d":"","o":["$6,000","$17,000","$37,000","$43,000"],"a":2,"cite":"Rev. Proc. 93-27; Rev. Proc. 2001-43; Reg. §1.721-1(b)(1); IRC §83","rat":"Plan 1: receipt of a capital interest is compensation of $100,000 ($37,000), and his basis becomes $100,000, so the later gain is $30,000 ($6,000): total $43,000.","ex":["This is the tax on the sale under Plan 1 ($6,000). It ignores the tax on the receipt of the capital interest.","Plan 1: receipt of a capital interest is compensation of $100,000 ($37,000), and his basis becomes $100,000, so the later gain is $30,000 ($6,000): total $43,000. Plan 2: the profits interest is not taxed on receipt and has no basis, so the whole $130,000 is capital gain ($26,000). The difference is $17,000.","This is only the tax on the receipt of the capital interest. Plan 2 also pays more tax on the sale because it has no basis.","This is the total under Plan 1 ($43,000), not the difference between the two plans."],"wt":["trap","","trap","calc"],"tags":{"area":"III","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A partnership interest received for services is taxed as compensation to the extent of its liquidation value, but a profits interest that meets the safe harbor is not taxed when received and has no basis.","from":"2026-01-01","calc":1,"steps":["Plan 1: compensation = 100,000 x 37% = 37,000; basis 100,000; gain on sale = 130,000 - 100,000 = 30,000 x 20% = 6,000; total 43,000","Plan 2: no tax on receipt; basis 0; gain = 130,000 x 20% = 26,000","Difference = 43,000 - 26,000 = 17,000"]}}]};
window.PAIRS=[];
